input.find:
for child in elem:
    tag = child.tag
    if tag == f"{ns}tbl":
        for row in child.iter(f"{ns}tr"):
            cells = []
            for cell in row.iter(f"{ns}tc"):
                cell_texts = [t.text for t in cell.iter(f"{ns}t") if t.text]
                cells.append("".join(cell_texts).strip())
            if any(cells):
                parts.append("\t".join(cells))
